        return 2
    }

    primary := primaryMetricsForTask(report.Model.TaskType)
    if primary == nil {
        fmt.Fprintf(os.Stderr, "unknown task type %q\n", report.Model.TaskType)
        return 2
    }
    if len(report.Splits) == 0 {
        fmt.Fprintln(os.Stderr, "report contains no splits")
        return 2
    }

    primaryMetrics := make(map[string]float64)
    metricValues := make([]string, 0, len(primary))
    for _, metric := range primary {
        vals := make([]float64, 0, len(report.Splits))
        for _, split := range report.Splits {
            if v, ok := split.Metrics[metric]; ok {
                vals = append(vals, v)
            }
        }
        if len(vals) == 0 {
            continue
        }
        avg := mean(vals)
        rounded := math.Round(avg*1e4) / 1e4
        if rounded == 0 {
