        primaryMetrics[metric] = rounded
        metricValues = append(metricValues, fmt.Sprintf("%s=%.4f", metric, avg))
    }

    if *jsonOutput {
        out := SummaryJSON{
            Model: SummaryModel{
                Name:     report.Model.Name,
                Version:  report.Model.Version,
                TaskType: report.Model.TaskType,
            },
            SplitCount:     len(report.Splits),
            PrimaryMetrics: primaryMetrics,
        }
        data, err := json.MarshalIndent(out, "", "  ")
        if err != nil {
            fmt.Fprintln(os.Stderr, err)
            return 2
        }
        fmt.Println(string(data))
        return 0
    }

    fmt.Printf("%s v%s (%s) — %d split(s): %s\n",
        report.Model.Name,
        report.Model.Version,
        report.Model.TaskType,
        len(report.Splits),
        strings.Join(metricValues, ", "))
    return 0
}
